# DEVASC Server (www.devasc-netacad.pka): Services > HTTP - HTTP Off, HTTPS On
user www-data;
worker_processes 1;
pid /run/nginx-DEVASC-Server.pid;
error_log /var/log/pt-lab/nginx-DEVASC-Server.error.log;
events {
    worker_connections 64;
}
http {
    include /etc/nginx/mime.types;
    access_log /var/log/pt-lab/nginx-DEVASC-Server.access.log;
    # блока server с listen 80 больше нет: HTTP выключен
    server {
        listen 192.168.2.3:443 ssl;
        server_name www.devasc-netacad.pka;
        ssl_certificate     /home/devasc/labs/devnet-src/pt-protocols/DEVASC-Server/devasc.crt;
        ssl_certificate_key /home/devasc/labs/devnet-src/pt-protocols/DEVASC-Server/devasc.key;
        root /srv/labnet/DEVASC-Server/www;
        index index.html;
    }
}
